`timescale 1ns/1ps

// P2F-B1 Step 10.2: resource-faithful shared reduction/butterfly kernel.
//
// The operation and event tables are generated mechanically from the frozen
// P2FDataflow graph.  There is one registered 128-lane multiplier farm, one
// shared reduction fabric (64/32/16/8/4 add slots), and one time-multiplexed
// butterfly fabric.  No per-dot product cache or per-bank reduction tree is
// instantiated.  The result port is guaranteed-accept; result_accept is only
// asserted in simulation and never stalls an admitted vector.
module p2f_dct2_64_b1_step102 #(
    parameter integer VECTOR_ID_W = 16
) (
    input  wire                         clk,
    input  wire                         rst_n,
    input  wire                         vector_start,
    input  wire [VECTOR_ID_W-1:0]       vector_id_in,
    input  wire [1023:0]                vector_data_flat,
    input  wire                         result_accept,

    output reg                          result_valid,
    output reg  [4:0]                   result_group,
    output reg  [VECTOR_ID_W-1:0]       result_vector_id,
    output reg                          result_first,
    output reg                          result_last,
    output reg  [159:0]                 result_raw_flat,
    output reg  [159:0]                 result_biased_flat,
    output reg  [159:0]                 result_shifted_flat,
    output reg  [63:0]                  result_stage16_flat,
    output reg  [39:0]                  result_final10_flat
);

`include "p2f_b1_tables.svh"
`include "p2f_step102_tables.svh"
`include "p2f_r4a_local_tables.svh"

`ifndef SYNTHESIS
    integer r3_terminal_trace_fd;
    initial r3_terminal_trace_fd = $fopen("p2f_b2_r3_terminal_dot_trace.log", "w");
    integer r3r_terminal_trace_fd;
    initial r3r_terminal_trace_fd = r3_terminal_trace_fd;
`endif

    localparam integer LANES = 128;
    localparam integer DOTS = 64;
    localparam integer SIGS = 124;
    localparam integer RESULT_BANKS = 4;

    // R4A: four physical cluster-local A/B vector copies.  The old single
    // global vector_buf_* arrays are intentionally removed from the active
    // datapath; each lane now selects only among three fixed local words.
    reg signed [15:0] r4a_vector_buf_a [0:R4A_CLUSTER_COUNT-1][0:63];
    reg signed [15:0] r4a_vector_buf_b [0:R4A_CLUSTER_COUNT-1][0:63];
    reg               r4a_issue_active [0:R4A_CLUSTER_COUNT-1];
    reg [4:0]         r4a_issue_cycle [0:R4A_CLUSTER_COUNT-1];
    reg               issue_active;
    reg               issue_bank;
    reg [4:0]         issue_cycle;
    reg [VECTOR_ID_W-1:0] issue_vector_id;
    // Start pulse delayed to the reduction/butterfly side only.  The issue
    // side still loads and decodes the vector immediately; D0/D1/M need three
    // extra edges before their first doubly-registered product is consumable.
    reg               vector_start_d1;
    reg               vector_start_d2;
    reg               vector_start_d3;
    reg [VECTOR_ID_W-1:0] vector_id_d1;
    reg [VECTOR_ID_W-1:0] vector_id_d2;
    reg [VECTOR_ID_W-1:0] vector_id_d3;

    // One and only one multiplier farm.  The front-end is explicitly split
    // into decode (D0), operand selection (D1), and registered multiply (M/P)
    // boundaries.  No issue-cycle/schedule function is on the multiplier
    // input path anymore.
    reg                sched_valid_reg [0:LANES-1];
    reg [6:0]          sched_src_reg [0:LANES-1];
    reg [1:0]          sched_src_sel_reg [0:LANES-1];
    reg signed [7:0]   sched_coeff_reg [0:LANES-1];
    integer            sched_op_id_reg [0:LANES-1];
    reg                sched_bank_reg [0:LANES-1];
    reg [VECTOR_ID_W-1:0] sched_vector_id_reg [0:LANES-1];
    reg                operand_valid_reg [0:LANES-1];
    reg signed [15:0]  operand_x_reg [0:LANES-1];
    reg signed [7:0]   operand_coeff_reg [0:LANES-1];
    integer            operand_op_id_reg [0:LANES-1];
    reg [VECTOR_ID_W-1:0] operand_vector_id_reg [0:LANES-1];
    reg                operand_bank_reg [0:LANES-1];
    reg signed [39:0] lane_product_comb [0:LANES-1];
    // The two data registers are deliberately separate from the control FSM.
    // With synchronous reset, Vivado can pack these boundaries into the
    // DSP48E2 M/P pipeline registers instead of leaving the full multiply and
    // ALU path between fabric registers.
    reg signed [39:0] lane_product_mreg [0:LANES-1];
    reg signed [39:0] lane_product_reg [0:LANES-1];
    reg                lane_valid_mreg [0:LANES-1];
    reg [VECTOR_ID_W-1:0] lane_vector_id_mreg [0:LANES-1];
    reg                lane_valid_reg [0:LANES-1];
    reg [VECTOR_ID_W-1:0] lane_vector_id_reg [0:LANES-1];

    // Shared registered reduction slots.  Each stage has exactly the A2
    // physical capacity; the arrays are not indexed by bank or dot.
    reg signed [39:0] red_s0_data [0:63];
    reg signed [39:0] red_s1_data [0:31];
    reg signed [39:0] red_s2_data [0:15];
    reg signed [39:0] red_s3_data [0:7];
    reg signed [39:0] red_s4_data [0:3];
    reg red_s0_valid [0:63];
    reg red_s1_valid [0:31];
    reg red_s2_valid [0:15];
    reg red_s3_valid [0:7];
    reg red_s4_valid [0:3];
    reg [VECTOR_ID_W-1:0] red_s0_vector [0:63];
    reg [VECTOR_ID_W-1:0] red_s1_vector [0:31];
    reg [VECTOR_ID_W-1:0] red_s2_vector [0:15];
    reg [VECTOR_ID_W-1:0] red_s3_vector [0:7];
    reg [VECTOR_ID_W-1:0] red_s4_vector [0:3];
    reg [6:0] red_s0_dot [0:63];
    reg [6:0] red_s1_dot [0:31];
    reg [6:0] red_s2_dot [0:15];
    reg [6:0] red_s3_dot [0:7];
    reg [6:0] red_s4_dot [0:3];
    reg [5:0] red_s0_terms [0:63];
    reg [5:0] red_s1_terms [0:31];
    reg [5:0] red_s2_terms [0:15];
    reg [5:0] red_s3_terms [0:7];
    reg [5:0] red_s4_terms [0:3];
    reg red_active;
    reg [5:0] red_cycle;

    // Dot results are the minimal intermediate state required by the proven
    // butterfly graph.  Two contexts are sufficient because successive
    // vectors use alternating input banks and the graph finishes before that
    // bank is reused.
    reg signed [39:0] dot_value_bank [0:1][0:63];
    reg dot_value_valid [0:1][0:63];
    reg [VECTOR_ID_W-1:0] dot_value_vector [0:1][0:63];

    // One shared registered signal store for the butterfly graph.  The event
    // tables limit physical add/sub work to the frozen per-level capacities.
    reg signed [39:0] signal_reg [0:SIGS-1];
    reg [VECTOR_ID_W-1:0] signal_vector [0:SIGS-1];
    reg bf_active;
    reg [5:0] bf_cycle;
    reg bf_bank;
    reg [VECTOR_ID_W-1:0] bf_vector_id;
    reg bf_pending;
    reg [5:0] bf_pending_cycle;
    reg bf_pending_bank;
    reg [VECTOR_ID_W-1:0] bf_pending_vector_id;
    reg capture_pending;
    reg capture_bank;
    reg [VECTOR_ID_W-1:0] capture_vector_id;

    // Four final result/reorder banks. Raw/biased/shifted are verification
    // observability only and disappear under SYNTHESIS. Stage16/final10 are
    // the implementation-facing reorder values.
`ifndef SYNTHESIS
    reg signed [39:0] raw_mem [0:RESULT_BANKS-1][0:63];
    reg signed [39:0] biased_mem [0:RESULT_BANKS-1][0:63];
    reg signed [39:0] shifted_mem [0:RESULT_BANKS-1][0:63];
`endif
    reg signed [15:0] stage16_mem [0:RESULT_BANKS-1][0:63];
    reg [9:0] final10_mem [0:RESULT_BANKS-1][0:63];
    reg result_ready [0:RESULT_BANKS-1];
    reg [VECTOR_ID_W-1:0] ready_vector_id [0:RESULT_BANKS-1];
    reg output_active;
    reg [1:0] output_bank;
    reg [4:0] output_group;
    reg [VECTOR_ID_W-1:0] output_vector_id;
    reg [VECTOR_ID_W-1:0] next_output_vector_id;

    function automatic signed [15:0] wrap16(input signed [39:0] v);
        begin wrap16 = v[15:0]; end
    endfunction
    function automatic signed [39:0] shift6(input signed [39:0] v);
        reg signed [39:0] b;
        begin b = v + 40'sd32; shift6 = b >>> 6; end
    endfunction

    wire [1:0] next_bank = next_output_vector_id[1:0];
    wire next_ready = result_ready[next_bank] &&
                      (ready_vector_id[next_bank] == next_output_vector_id);

    integer l, i, s, r, d, b, c;
    integer op_tmp, src_tmp;
    integer key_tmp, sid_tmp, esig_tmp, edot_tmp, odot_tmp;
    integer bf_val_high;
    reg signed [39:0] even_tmp, odd_tmp, bf_result_tmp;
    integer sched_op_id_comb [0:LANES-1];
    reg [6:0] sched_src_comb [0:LANES-1];
    reg signed [7:0] sched_coeff_comb [0:LANES-1];
    reg sched_valid_comb [0:LANES-1];
    reg [3:0] sched_phase_comb [0:LANES-1];

    // R3R_STATIC_SUM_BEGIN
    // Static current-cycle reduction values.  Every source index below
    // is an elaboration-time constant; only the legal two-choice slots
    // have a small red_cycle-controlled override.
    reg signed [39:0] r3r_s0_sum_now [0:63];
    reg [VECTOR_ID_W-1:0] r3r_s0_vector_now [0:63];
    reg signed [39:0] r3r_s1_sum_now [0:31];
    reg [VECTOR_ID_W-1:0] r3r_s1_vector_now [0:31];
    reg signed [39:0] r3r_s2_sum_now [0:15];
    reg [VECTOR_ID_W-1:0] r3r_s2_vector_now [0:15];
    reg signed [39:0] r3r_s3_sum_now [0:7];
    reg [VECTOR_ID_W-1:0] r3r_s3_vector_now [0:7];
    reg signed [39:0] r3r_s4_sum_now [0:3];
    reg [VECTOR_ID_W-1:0] r3r_s4_vector_now [0:3];
    integer r3r_idx;
    always @* begin
        r3r_s0_sum_now[0] = lane_product_reg[0] + lane_product_reg[1];
        r3r_s0_vector_now[0] = lane_vector_id_reg[0];
        r3r_s0_sum_now[1] = lane_product_reg[2] + lane_product_reg[3];
        r3r_s0_vector_now[1] = lane_vector_id_reg[2];
        r3r_s0_sum_now[2] = lane_product_reg[4] + lane_product_reg[5];
        r3r_s0_vector_now[2] = lane_vector_id_reg[4];
        r3r_s0_sum_now[3] = lane_product_reg[6] + lane_product_reg[7];
        r3r_s0_vector_now[3] = lane_vector_id_reg[6];
        r3r_s0_sum_now[4] = lane_product_reg[8] + lane_product_reg[9];
        r3r_s0_vector_now[4] = lane_vector_id_reg[8];
        r3r_s0_sum_now[5] = lane_product_reg[10] + lane_product_reg[11];
        r3r_s0_vector_now[5] = lane_vector_id_reg[10];
        r3r_s0_sum_now[6] = lane_product_reg[12] + lane_product_reg[13];
        r3r_s0_vector_now[6] = lane_vector_id_reg[12];
        r3r_s0_sum_now[7] = lane_product_reg[14] + lane_product_reg[15];
        r3r_s0_vector_now[7] = lane_vector_id_reg[14];
        r3r_s0_sum_now[8] = lane_product_reg[16] + lane_product_reg[17];
        r3r_s0_vector_now[8] = lane_vector_id_reg[16];
        r3r_s0_sum_now[9] = lane_product_reg[18] + lane_product_reg[19];
        r3r_s0_vector_now[9] = lane_vector_id_reg[18];
        r3r_s0_sum_now[10] = lane_product_reg[20] + lane_product_reg[21];
        r3r_s0_vector_now[10] = lane_vector_id_reg[20];
        r3r_s0_sum_now[11] = lane_product_reg[22] + lane_product_reg[23];
        r3r_s0_vector_now[11] = lane_vector_id_reg[22];
        r3r_s0_sum_now[12] = lane_product_reg[24] + lane_product_reg[25];
        r3r_s0_vector_now[12] = lane_vector_id_reg[24];
        r3r_s0_sum_now[13] = lane_product_reg[26] + lane_product_reg[27];
        r3r_s0_vector_now[13] = lane_vector_id_reg[26];
        r3r_s0_sum_now[14] = lane_product_reg[28] + lane_product_reg[29];
        r3r_s0_vector_now[14] = lane_vector_id_reg[28];
        r3r_s0_sum_now[15] = lane_product_reg[30] + lane_product_reg[31];
        r3r_s0_vector_now[15] = lane_vector_id_reg[30];
        r3r_s0_sum_now[16] = lane_product_reg[32] + lane_product_reg[33];
        r3r_s0_vector_now[16] = lane_vector_id_reg[32];
        r3r_s0_sum_now[17] = lane_product_reg[34] + lane_product_reg[35];
        r3r_s0_vector_now[17] = lane_vector_id_reg[34];
        r3r_s0_sum_now[18] = lane_product_reg[36] + lane_product_reg[37];
        r3r_s0_vector_now[18] = lane_vector_id_reg[36];
        r3r_s0_sum_now[19] = lane_product_reg[38] + lane_product_reg[39];
        r3r_s0_vector_now[19] = lane_vector_id_reg[38];
        r3r_s0_sum_now[20] = lane_product_reg[40] + lane_product_reg[41];
        r3r_s0_vector_now[20] = lane_vector_id_reg[40];
        r3r_s0_sum_now[21] = lane_product_reg[42] + lane_product_reg[43];
        r3r_s0_vector_now[21] = lane_vector_id_reg[42];
        r3r_s0_sum_now[22] = lane_product_reg[44] + lane_product_reg[45];
        r3r_s0_vector_now[22] = lane_vector_id_reg[44];
        r3r_s0_sum_now[23] = lane_product_reg[46] + lane_product_reg[47];
        r3r_s0_vector_now[23] = lane_vector_id_reg[46];
        r3r_s0_sum_now[24] = lane_product_reg[48] + lane_product_reg[49];
        r3r_s0_vector_now[24] = lane_vector_id_reg[48];
        r3r_s0_sum_now[25] = lane_product_reg[50] + lane_product_reg[51];
        r3r_s0_vector_now[25] = lane_vector_id_reg[50];
        r3r_s0_sum_now[26] = lane_product_reg[52] + lane_product_reg[53];
        r3r_s0_vector_now[26] = lane_vector_id_reg[52];
        r3r_s0_sum_now[27] = lane_product_reg[54] + lane_product_reg[55];
        r3r_s0_vector_now[27] = lane_vector_id_reg[54];
        r3r_s0_sum_now[28] = lane_product_reg[56] + lane_product_reg[57];
        r3r_s0_vector_now[28] = lane_vector_id_reg[56];
        r3r_s0_sum_now[29] = lane_product_reg[58] + lane_product_reg[59];
        r3r_s0_vector_now[29] = lane_vector_id_reg[58];
        r3r_s0_sum_now[30] = lane_product_reg[60] + lane_product_reg[61];
        r3r_s0_vector_now[30] = lane_vector_id_reg[60];
        r3r_s0_sum_now[31] = lane_product_reg[62] + lane_product_reg[63];
        r3r_s0_vector_now[31] = lane_vector_id_reg[62];
        r3r_s0_sum_now[32] = lane_product_reg[64] + lane_product_reg[65];
        r3r_s0_vector_now[32] = lane_vector_id_reg[64];
        r3r_s0_sum_now[33] = lane_product_reg[66] + lane_product_reg[67];
        r3r_s0_vector_now[33] = lane_vector_id_reg[66];
        r3r_s0_sum_now[34] = lane_product_reg[68] + lane_product_reg[69];
        r3r_s0_vector_now[34] = lane_vector_id_reg[68];
        r3r_s0_sum_now[35] = lane_product_reg[70] + lane_product_reg[71];
        r3r_s0_vector_now[35] = lane_vector_id_reg[70];
        r3r_s0_sum_now[36] = lane_product_reg[72] + lane_product_reg[73];
        r3r_s0_vector_now[36] = lane_vector_id_reg[72];
        r3r_s0_sum_now[37] = lane_product_reg[74] + lane_product_reg[75];
        r3r_s0_vector_now[37] = lane_vector_id_reg[74];
        r3r_s0_sum_now[38] = lane_product_reg[76] + lane_product_reg[77];
        r3r_s0_vector_now[38] = lane_vector_id_reg[76];
        r3r_s0_sum_now[39] = lane_product_reg[78] + lane_product_reg[79];
        r3r_s0_vector_now[39] = lane_vector_id_reg[78];
        r3r_s0_sum_now[40] = lane_product_reg[80] + lane_product_reg[81];
        r3r_s0_vector_now[40] = lane_vector_id_reg[80];
        r3r_s0_sum_now[41] = lane_product_reg[82] + lane_product_reg[83];
        r3r_s0_vector_now[41] = lane_vector_id_reg[82];
        r3r_s0_sum_now[42] = lane_product_reg[84] + lane_product_reg[85];
        r3r_s0_vector_now[42] = lane_vector_id_reg[84];
        r3r_s0_sum_now[43] = lane_product_reg[86] + lane_product_reg[87];
        r3r_s0_vector_now[43] = lane_vector_id_reg[86];
        r3r_s0_sum_now[44] = lane_product_reg[88] + lane_product_reg[89];
        r3r_s0_vector_now[44] = lane_vector_id_reg[88];
        r3r_s0_sum_now[45] = lane_product_reg[90] + lane_product_reg[91];
        r3r_s0_vector_now[45] = lane_vector_id_reg[90];
        r3r_s0_sum_now[46] = lane_product_reg[92] + lane_product_reg[93];
        r3r_s0_vector_now[46] = lane_vector_id_reg[92];
        r3r_s0_sum_now[47] = lane_product_reg[94] + lane_product_reg[95];
        r3r_s0_vector_now[47] = lane_vector_id_reg[94];
        r3r_s0_sum_now[48] = lane_product_reg[96] + lane_product_reg[97];
        r3r_s0_vector_now[48] = lane_vector_id_reg[96];
        r3r_s0_sum_now[49] = lane_product_reg[98] + lane_product_reg[99];
        r3r_s0_vector_now[49] = lane_vector_id_reg[98];
        r3r_s0_sum_now[50] = lane_product_reg[100] + lane_product_reg[101];
        r3r_s0_vector_now[50] = lane_vector_id_reg[100];
        r3r_s0_sum_now[51] = lane_product_reg[102] + lane_product_reg[103];
        r3r_s0_vector_now[51] = lane_vector_id_reg[102];
        r3r_s0_sum_now[52] = lane_product_reg[104] + lane_product_reg[105];
        r3r_s0_vector_now[52] = lane_vector_id_reg[104];
        r3r_s0_sum_now[53] = lane_product_reg[106] + lane_product_reg[107];
        r3r_s0_vector_now[53] = lane_vector_id_reg[106];
        r3r_s0_sum_now[54] = lane_product_reg[108] + lane_product_reg[109];
        r3r_s0_vector_now[54] = lane_vector_id_reg[108];
        r3r_s0_sum_now[55] = lane_product_reg[110] + lane_product_reg[111];
        r3r_s0_vector_now[55] = lane_vector_id_reg[110];
        r3r_s0_sum_now[56] = lane_product_reg[112] + lane_product_reg[113];
        r3r_s0_vector_now[56] = lane_vector_id_reg[112];
        r3r_s0_sum_now[57] = lane_product_reg[114] + lane_product_reg[115];
        r3r_s0_vector_now[57] = lane_vector_id_reg[114];
        r3r_s0_sum_now[58] = lane_product_reg[116] + lane_product_reg[117];
        r3r_s0_vector_now[58] = lane_vector_id_reg[116];
        r3r_s0_sum_now[59] = lane_product_reg[118] + lane_product_reg[119];
        r3r_s0_vector_now[59] = lane_vector_id_reg[118];
        r3r_s0_sum_now[60] = lane_product_reg[120] + lane_product_reg[121];
        r3r_s0_vector_now[60] = lane_vector_id_reg[120];
        r3r_s0_sum_now[61] = lane_product_reg[122] + lane_product_reg[123];
        r3r_s0_vector_now[61] = lane_vector_id_reg[122];
        r3r_s0_sum_now[62] = lane_product_reg[124] + lane_product_reg[125];
        r3r_s0_vector_now[62] = lane_vector_id_reg[124];
        r3r_s0_sum_now[63] = lane_product_reg[126] + lane_product_reg[127];
        r3r_s0_vector_now[63] = lane_vector_id_reg[126];
        r3r_s1_sum_now[0] = red_s0_data[0] + red_s0_data[1];
        r3r_s1_vector_now[0] = red_s0_vector[0];
        r3r_s1_sum_now[1] = red_s0_data[2] + red_s0_data[3];
        r3r_s1_vector_now[1] = red_s0_vector[2];
        r3r_s1_sum_now[2] = red_s0_data[4] + red_s0_data[5];
        r3r_s1_vector_now[2] = red_s0_vector[4];
        r3r_s1_sum_now[3] = red_s0_data[6] + red_s0_data[7];
        r3r_s1_vector_now[3] = red_s0_vector[6];
        r3r_s1_sum_now[4] = red_s0_data[8] + red_s0_data[9];
        r3r_s1_vector_now[4] = red_s0_vector[8];
        r3r_s1_sum_now[5] = red_s0_data[10] + red_s0_data[11];
        r3r_s1_vector_now[5] = red_s0_vector[10];
        r3r_s1_sum_now[6] = red_s0_data[12] + red_s0_data[13];
        r3r_s1_vector_now[6] = red_s0_vector[12];
        r3r_s1_sum_now[7] = red_s0_data[14] + red_s0_data[15];
        r3r_s1_vector_now[7] = red_s0_vector[14];
        r3r_s1_sum_now[8] = red_s0_data[16] + red_s0_data[17];
