        r3r_s3_sum_now[7] = red_s2_data[14] + red_s2_data[15];
        r3r_s3_vector_now[7] = red_s2_vector[14];
        r3r_s4_sum_now[0] = red_s3_data[0] + red_s3_data[1];
        r3r_s4_vector_now[0] = red_s3_vector[0];
        r3r_s4_sum_now[1] = red_s3_data[2] + red_s3_data[3];
