            r3r_s1_vector_now[1] = red_s0_vector[6];
        end
        if (red_cycle == 6'd3) begin
            r3r_s1_sum_now[2] = red_s0_data[8] + red_s0_data[9];
            r3r_s1_vector_now[2] = red_s0_vector[8];
        end
        if (red_cycle == 6'd3) begin
