            r3r_s2_sum_now[6] = red_s1_data[16] + red_s1_data[17];
            r3r_s2_vector_now[6] = red_s1_vector[16];
        end
        if (red_cycle == 6'd4) begin
            r3r_s2_sum_now[7] = red_s1_data[18] + red_s1_data[19];
            r3r_s2_vector_now[7] = red_s1_vector[18];
        end
    end
    // R3R_STATIC_SUM_END

    // Stage D0: R4A lane-local schedule table.  The phase is replicated per
    // cluster and the source/coefficient values are fixed table entries;
    // there is no global op/source dynamic decoder on this datapath.
    always @* begin
        for (l = 0; l < LANES; l = l + 1) begin
            sched_op_id_comb[l] = -1;
            sched_src_comb[l] = 0;
            sched_coeff_comb[l] = 0;
            sched_valid_comb[l] = 1'b0;
            sched_phase_comb[l] = 4'd0;
            if (r4a_issue_active[l / R4A_LANES_PER_CLUSTER]) begin
                sched_phase_comb[l] = r4a_issue_cycle[l / R4A_LANES_PER_CLUSTER];
                if (R4A_VALID[l][sched_phase_comb[l]]) begin
                    sched_op_id_comb[l] = R4A_OP_ID[l][sched_phase_comb[l]];
                    sched_src_comb[l] = R4A_SRC_ID[l][R4A_SRC_SEL[l][sched_phase_comb[l]]];
                    sched_coeff_comb[l] = R4A_COEFF[l][sched_phase_comb[l]];
                    sched_valid_comb[l] = 1'b1;
                end
            end
        end
    end

    // Stage M/P: only registered operands feed the multiplier.  The product
    // is widened to the signed 40-bit raw path before any reduction.  The
    // operands are already forced to zero when the corresponding schedule
    // slot is invalid, so the multiply is intentionally unconditional.  This
    // avoids inferring a post-DSP validity mux on the product path and gives
    // Vivado a clean opportunity to use DSP48E2 MREG/PREG.
    always @* begin
        for (l = 0; l < LANES; l = l + 1) begin
            // Explicitly widen both operands before multiplication.  A
            // bare 8x16 expression is only 16 bits in Verilog sizing; the
            // 24-bit sign-extended operands preserve the complete signed16 x
            // signed8 product before extension to 40 bits.
            lane_product_comb[l] =
                $signed({{16{operand_coeff_reg[l][7]}}, operand_coeff_reg[l]}) *
                $signed({{8{operand_x_reg[l][15]}}, operand_x_reg[l]});
        end
    end

    // Data-only multiplier pipeline.  It has a synchronous reset so that the
    // data registers remain eligible for DSP48E2 internal M/P packing;
    // asynchronous reset is retained for the control/tag state below.  The
    // valid/tag pipeline is advanced in lock-step in the control process.
    always @(posedge clk) begin
        if (!rst_n) begin
            for (l = 0; l < LANES; l = l + 1) begin
                lane_product_mreg[l] <= 40'sd0;
                lane_product_reg[l] <= 40'sd0;
            end
        end else begin
            for (l = 0; l < LANES; l = l + 1) begin
                lane_product_mreg[l] <= lane_product_comb[l];
                lane_product_reg[l] <= lane_product_mreg[l];
            end
        end
    end

    function automatic signed [39:0] root_value(input integer root_index);
        begin root_value = signal_reg[p2f_root_sig(root_index)]; end
    endfunction

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            issue_active <= 1'b0;
            issue_bank <= 1'b0;
            issue_cycle <= 5'd0;
            issue_vector_id <= {VECTOR_ID_W{1'b0}};
            vector_start_d1 <= 1'b0;
            vector_start_d2 <= 1'b0;
            vector_start_d3 <= 1'b0;
            vector_id_d1 <= {VECTOR_ID_W{1'b0}};
            vector_id_d2 <= {VECTOR_ID_W{1'b0}};
            vector_id_d3 <= {VECTOR_ID_W{1'b0}};
            for (c = 0; c < R4A_CLUSTER_COUNT; c = c + 1) begin
                r4a_issue_active[c] <= 1'b0;
                r4a_issue_cycle[c] <= 5'd0;
                for (i = 0; i < 64; i = i + 1) begin
                    r4a_vector_buf_a[c][i] <= 16'sd0;
                    r4a_vector_buf_b[c][i] <= 16'sd0;
                end
            end
            red_active <= 1'b0;
            red_cycle <= 6'd0;
            bf_active <= 1'b0;
            bf_cycle <= 6'd0;
            bf_bank <= 1'b0;
            bf_vector_id <= {VECTOR_ID_W{1'b0}};
            bf_pending <= 1'b0;
            bf_pending_cycle <= 6'd0;
            capture_pending <= 1'b0;
            output_active <= 1'b0;
            output_bank <= 2'd0;
            output_group <= 5'd0;
            output_vector_id <= {VECTOR_ID_W{1'b0}};
            next_output_vector_id <= {VECTOR_ID_W{1'b0}};
            for (l = 0; l < LANES; l = l + 1) begin
                sched_valid_reg[l] <= 1'b0;
                sched_src_reg[l] <= 7'd0;
                sched_src_sel_reg[l] <= 2'd0;
                sched_coeff_reg[l] <= 8'sd0;
                sched_op_id_reg[l] <= -1;
                sched_bank_reg[l] <= 1'b0;
                sched_vector_id_reg[l] <= {VECTOR_ID_W{1'b0}};
                operand_valid_reg[l] <= 1'b0;
                operand_x_reg[l] <= 16'sd0;
                operand_coeff_reg[l] <= 8'sd0;
                operand_op_id_reg[l] <= -1;
                operand_vector_id_reg[l] <= {VECTOR_ID_W{1'b0}};
                operand_bank_reg[l] <= 1'b0;
                lane_valid_mreg[l] <= 1'b0;
                lane_vector_id_mreg[l] <= {VECTOR_ID_W{1'b0}};
                lane_valid_reg[l] <= 1'b0;
                lane_vector_id_reg[l] <= {VECTOR_ID_W{1'b0}};
            end
            for (r = 0; r < 64; r = r + 1) begin
                red_s0_valid[r] <= 1'b0;
                red_s0_data[r] <= 40'sd0;
                red_s0_vector[r] <= {VECTOR_ID_W{1'b0}};
                red_s0_dot[r] <= 7'd0;
                red_s0_terms[r] <= 6'd0;
            end
            for (r = 0; r < 32; r = r + 1) begin
                red_s1_valid[r] <= 1'b0;
                red_s1_data[r] <= 40'sd0;
                red_s1_vector[r] <= {VECTOR_ID_W{1'b0}};
                red_s1_dot[r] <= 7'd0;
                red_s1_terms[r] <= 6'd0;
            end
            for (r = 0; r < 16; r = r + 1) begin
                red_s2_valid[r] <= 1'b0;
                red_s2_data[r] <= 40'sd0;
                red_s2_vector[r] <= {VECTOR_ID_W{1'b0}};
                red_s2_dot[r] <= 7'd0;
                red_s2_terms[r] <= 6'd0;
            end
            for (r = 0; r < 8; r = r + 1) begin
                red_s3_valid[r] <= 1'b0;
                red_s3_data[r] <= 40'sd0;
                red_s3_vector[r] <= {VECTOR_ID_W{1'b0}};
                red_s3_dot[r] <= 7'd0;
                red_s3_terms[r] <= 6'd0;
            end
            for (r = 0; r < 4; r = r + 1) begin
                red_s4_valid[r] <= 1'b0;
                red_s4_data[r] <= 40'sd0;
                red_s4_vector[r] <= {VECTOR_ID_W{1'b0}};
                red_s4_dot[r] <= 7'd0;
                red_s4_terms[r] <= 6'd0;
            end
            for (d = 0; d < DOTS; d = d + 1) begin
                dot_value_bank[0][d] <= 40'sd0;
                dot_value_bank[1][d] <= 40'sd0;
                dot_value_valid[0][d] <= 1'b0;
                dot_value_valid[1][d] <= 1'b0;
                dot_value_vector[0][d] <= {VECTOR_ID_W{1'b0}};
                dot_value_vector[1][d] <= {VECTOR_ID_W{1'b0}};
            end
            for (s = 0; s < SIGS; s = s + 1) begin
                signal_reg[s] <= 40'sd0;
                signal_vector[s] <= {VECTOR_ID_W{1'b0}};
            end
            for (b = 0; b < RESULT_BANKS; b = b + 1) begin
                result_ready[b] <= 1'b0;
                ready_vector_id[b] <= {VECTOR_ID_W{1'b0}};
                for (i = 0; i < 64; i = i + 1) begin
`ifndef SYNTHESIS
                    raw_mem[b][i] <= 40'sd0;
                    biased_mem[b][i] <= 40'sd0;
                    shifted_mem[b][i] <= 40'sd0;
`endif
                    stage16_mem[b][i] <= 16'sd0;
                    final10_mem[b][i] <= 10'd0;
                end
            end
        end else begin
            // Keep the issue side at the original vector-start timing, but
            // delay reduction/butterfly context by three clocks so the new
            // D0, D1 and M/P multiplier-register boundaries are populated.
            vector_start_d1 <= vector_start;
            vector_start_d2 <= vector_start_d1;
            vector_start_d3 <= vector_start_d2;
            vector_id_d1 <= vector_id_in;
            vector_id_d2 <= vector_id_d1;
            vector_id_d3 <= vector_id_d2;

            // D0: register lane-local schedule values.  D1: select from the
