                sched_src_reg[l] <= sched_src_comb[l];
                sched_src_sel_reg[l] <= R4A_SRC_SEL[l][sched_phase_comb[l]];
                sched_coeff_reg[l] <= sched_coeff_comb[l];
                sched_op_id_reg[l] <= sched_op_id_comb[l];
                sched_bank_reg[l] <= issue_bank;
                sched_vector_id_reg[l] <= issue_vector_id;
                operand_valid_reg[l] <= sched_valid_reg[l];
                operand_coeff_reg[l] <= sched_coeff_reg[l];
                operand_op_id_reg[l] <= sched_op_id_reg[l];
                operand_vector_id_reg[l] <= sched_vector_id_reg[l];
                operand_bank_reg[l] <= sched_bank_reg[l];
                if (sched_valid_reg[l]) begin
                    case (sched_src_sel_reg[l])
                        2'd0: begin
                            if (sched_bank_reg[l])
                                operand_x_reg[l] <= r4a_vector_buf_b[l / R4A_LANES_PER_CLUSTER][R4A_SRC_ID[l][0]];
                            else
                                operand_x_reg[l] <= r4a_vector_buf_a[l / R4A_LANES_PER_CLUSTER][R4A_SRC_ID[l][0]];
                        end
                        2'd1: begin
                            if (sched_bank_reg[l])
                                operand_x_reg[l] <= r4a_vector_buf_b[l / R4A_LANES_PER_CLUSTER][R4A_SRC_ID[l][1]];
                            else
                                operand_x_reg[l] <= r4a_vector_buf_a[l / R4A_LANES_PER_CLUSTER][R4A_SRC_ID[l][1]];
                        end
                        default: begin
                            if (sched_bank_reg[l])
                                operand_x_reg[l] <= r4a_vector_buf_b[l / R4A_LANES_PER_CLUSTER][R4A_SRC_ID[l][2]];
                            else
                                operand_x_reg[l] <= r4a_vector_buf_a[l / R4A_LANES_PER_CLUSTER][R4A_SRC_ID[l][2]];
                        end
                    endcase
                end else begin
                    operand_x_reg[l] <= 16'sd0;
                end

