                // product data itself is driven only by the synchronous data
                // pipeline, avoiding a fabric register between the DSP and
                // reduction input when the DSP can absorb MREG/PREG.
                lane_valid_mreg[l] <= operand_valid_reg[l];
                lane_vector_id_mreg[l] <= operand_vector_id_reg[l];
                lane_valid_reg[l] <= lane_valid_mreg[l];
                lane_vector_id_reg[l] <= lane_vector_id_mreg[l];
            end

