                        dot_value_vector[r3r_s4_vector_now[0][0]][56] <= r3r_s4_vector_now[0];
                        dot_value_bank[r3r_s4_vector_now[1][0]][57] <= r3r_s4_sum_now[1];
`ifndef SYNTHESIS
                        $fwrite(r3r_terminal_trace_fd, "%0t,%0d,57,%0d,%0d\n", $time, r3r_s4_vector_now[1], red_cycle, r3r_s4_sum_now[1]);
`endif
                        dot_value_valid[r3r_s4_vector_now[1][0]][57] <= 1'b1;
                        dot_value_vector[r3r_s4_vector_now[1][0]][57] <= r3r_s4_vector_now[1];
                        dot_value_bank[r3r_s4_vector_now[2][0]][58] <= r3r_s4_sum_now[2];
`ifndef SYNTHESIS
                        $fwrite(r3r_terminal_trace_fd, "%0t,%0d,58,%0d,%0d\n", $time, r3r_s4_vector_now[2], red_cycle, r3r_s4_sum_now[2]);
`endif
                        dot_value_valid[r3r_s4_vector_now[2][0]][58] <= 1'b1;
                        dot_value_vector[r3r_s4_vector_now[2][0]][58] <= r3r_s4_vector_now[2];
                        dot_value_bank[r3r_s4_vector_now[3][0]][59] <= r3r_s4_sum_now[3];
`ifndef SYNTHESIS
                        $fwrite(r3r_terminal_trace_fd, "%0t,%0d,59,%0d,%0d\n", $time, r3r_s4_vector_now[3], red_cycle, r3r_s4_sum_now[3]);
`endif
                        dot_value_valid[r3r_s4_vector_now[3][0]][59] <= 1'b1;
                        dot_value_vector[r3r_s4_vector_now[3][0]][59] <= r3r_s4_vector_now[3];
                    end
                    6'd16: begin
                        dot_value_bank[r3r_s4_vector_now[0][0]][60] <= r3r_s4_sum_now[0];
`ifndef SYNTHESIS
                        $fwrite(r3r_terminal_trace_fd, "%0t,%0d,60,%0d,%0d\n", $time, r3r_s4_vector_now[0], red_cycle, r3r_s4_sum_now[0]);
`endif
                        dot_value_valid[r3r_s4_vector_now[0][0]][60] <= 1'b1;
                        dot_value_vector[r3r_s4_vector_now[0][0]][60] <= r3r_s4_vector_now[0];
                        dot_value_bank[r3r_s4_vector_now[1][0]][61] <= r3r_s4_sum_now[1];
`ifndef SYNTHESIS
                        $fwrite(r3r_terminal_trace_fd, "%0t,%0d,61,%0d,%0d\n", $time, r3r_s4_vector_now[1], red_cycle, r3r_s4_sum_now[1]);
`endif
                        dot_value_valid[r3r_s4_vector_now[1][0]][61] <= 1'b1;
                        dot_value_vector[r3r_s4_vector_now[1][0]][61] <= r3r_s4_vector_now[1];
                        dot_value_bank[r3r_s4_vector_now[2][0]][62] <= r3r_s4_sum_now[2];
`ifndef SYNTHESIS
                        $fwrite(r3r_terminal_trace_fd, "%0t,%0d,62,%0d,%0d\n", $time, r3r_s4_vector_now[2], red_cycle, r3r_s4_sum_now[2]);
`endif
                        dot_value_valid[r3r_s4_vector_now[2][0]][62] <= 1'b1;
                        dot_value_vector[r3r_s4_vector_now[2][0]][62] <= r3r_s4_vector_now[2];
                        dot_value_bank[r3r_s4_vector_now[3][0]][63] <= r3r_s4_sum_now[3];
`ifndef SYNTHESIS
                        $fwrite(r3r_terminal_trace_fd, "%0t,%0d,63,%0d,%0d\n", $time, r3r_s4_vector_now[3], red_cycle, r3r_s4_sum_now[3]);
`endif
                        dot_value_valid[r3r_s4_vector_now[3][0]][63] <= 1'b1;
                        dot_value_vector[r3r_s4_vector_now[3][0]][63] <= r3r_s4_vector_now[3];
                    end
                    default: begin end
                endcase
            end
            // R3R_STATIC_TERMINAL_END

            // R4B event-unrolled butterfly fabric.  Source and destination IDs are fixed by the audited 124-event graph; only context (bank/vector) remains dynamic.
`include "p2f_r4b_static_butterfly.svh"

            // Capture one edge after the last root butterfly has registered.
            if (capture_pending) begin
                capture_pending <= 1'b0;
                for (i = 0; i < 64; i = i + 1) begin
`ifndef SYNTHESIS
                    raw_mem[capture_vector_id[1:0]][i] <= root_value(i);
                    biased_mem[capture_vector_id[1:0]][i] <= root_value(i) + 40'sd32;
                    shifted_mem[capture_vector_id[1:0]][i] <= shift6(root_value(i));
`endif
                    stage16_mem[capture_vector_id[1:0]][i] <= wrap16(shift6(root_value(i)));
                    final10_mem[capture_vector_id[1:0]][i] <= shift6(root_value(i));
                end
                result_ready[capture_vector_id[1:0]] <= 1'b1;
                ready_vector_id[capture_vector_id[1:0]] <= capture_vector_id;
            end

            // Issue-side state. A new vector is admitted without stalling an
            // already-started product/reduction/butterfly burst.
            if (vector_start) begin
                if (issue_active) $error("Step102 vector_start while issue burst active");
                issue_active <= 1'b1;
                issue_bank <= vector_id_in[0];
                issue_cycle <= 5'd0;
                issue_vector_id <= vector_id_in;
                for (c = 0; c < R4A_CLUSTER_COUNT; c = c + 1) begin
                    r4a_issue_active[c] <= 1'b1;
                    r4a_issue_cycle[c] <= 5'd0;
                    if (vector_id_in[0])
                        for (i = 0; i < 64; i = i + 1) r4a_vector_buf_b[c][i] <= $signed(vector_data_flat[i*16 +: 16]);
                    else
                        for (i = 0; i < 64; i = i + 1) r4a_vector_buf_a[c][i] <= $signed(vector_data_flat[i*16 +: 16]);
                end
            end else if (issue_active) begin
                if (issue_cycle == 5'd10) begin
                    issue_active <= 1'b0;
                    for (c = 0; c < R4A_CLUSTER_COUNT; c = c + 1) r4a_issue_active[c] <= 1'b0;
                end else begin
                    issue_cycle <= issue_cycle + 5'd1;
                    for (c = 0; c < R4A_CLUSTER_COUNT; c = c + 1)
                        r4a_issue_cycle[c] <= issue_cycle + 5'd1;
                end
            end else begin
                for (c = 0; c < R4A_CLUSTER_COUNT; c = c + 1) r4a_issue_active[c] <= 1'b0;
            end

            // The delayed context launch is deliberately separate from the
            // issue launch.  This is the only timing adjustment introduced by
            // the front-end repair; event numbers and the generated graph are
            // unchanged.
            if (vector_start_d3) begin
                red_active <= 1'b1;
                red_cycle <= 6'd1;
                if (!bf_active) begin
                    bf_active <= 1'b1;
                    bf_cycle <= 6'd1;
                    bf_bank <= vector_id_d3[0];
                    bf_vector_id <= vector_id_d3;
                end else begin
                    if (bf_pending) $error("Step102 butterfly pending overflow");
                    bf_pending <= 1'b1;
                    bf_pending_cycle <= 6'd2;
                    bf_pending_bank <= vector_id_d3[0];
                    bf_pending_vector_id <= vector_id_d3;
                end
            end

            // The input start pulse is two clocks earlier than this delayed
            // context.  Do not stall the active reduction counter on the
            // original issue pulse; only the delayed context launch resets
            // it.  This preserves one event per red-cycle number (including
            // the final c16 event) across II=16 vector boundaries.
            if (red_active && !vector_start_d3) begin
                if (red_cycle == 6'd17) red_active <= 1'b0;
                else red_cycle <= red_cycle + 6'd1;
            end

            // Preserve the original event-fabric update ordering: the
            // pending-context launch and the active butterfly counter are
            // both evaluated on a vector boundary.  Only the reduction
            // counter is held on delayed start; BF must still advance here.
            if (bf_active) begin
                if (bf_cycle == 6'd17) begin
                    capture_pending <= 1'b1;
                    capture_bank <= bf_bank;
                    capture_vector_id <= bf_vector_id;
                    if (bf_pending) begin
                        bf_cycle <= bf_pending_cycle;
                        bf_bank <= bf_pending_bank;
                        bf_vector_id <= bf_pending_vector_id;
                        bf_pending <= 1'b0;
                    end else begin
                        bf_active <= 1'b0;
                    end
                end else begin
                    bf_cycle <= bf_cycle + 6'd1;
                    if (bf_pending)
                        bf_pending_cycle <= bf_pending_cycle + 6'd1;
                end
            end

            // Output reorder port. It is only read when a complete result
            // bank is ready; result_accept is deliberately absent here.
            if (output_active) begin
                if (output_group == 5'd15) begin
                    result_ready[output_bank] <= 1'b0;
                    if (next_ready) begin
                        output_active <= 1'b1;
                        output_bank <= next_bank;
                        output_group <= 5'd0;
                        output_vector_id <= next_output_vector_id;
                        next_output_vector_id <= next_output_vector_id + 1'b1;
                    end else begin
                        output_active <= 1'b0;
                    end
                end else begin
                    output_group <= output_group + 5'd1;
                end
            end else if (next_ready) begin
                output_active <= 1'b1;
                output_bank <= next_bank;
                output_group <= 5'd0;
                output_vector_id <= next_output_vector_id;
                next_output_vector_id <= next_output_vector_id + 1'b1;
            end

        end
    end

    always @* begin
        result_valid = output_active;
        result_group = output_group;
        result_vector_id = output_vector_id;
        result_first = output_active && (output_group == 5'd0);
        result_last = output_active && (output_group == 5'd15);
        result_raw_flat = 160'd0;
        result_biased_flat = 160'd0;
        result_shifted_flat = 160'd0;
        result_stage16_flat = 64'd0;
        result_final10_flat = 40'd0;
        if (output_active) begin
            for (i = 0; i < 4; i = i + 1) begin
`ifndef SYNTHESIS
                result_raw_flat[i*40 +: 40] = raw_mem[output_bank][output_group*4+i];
                result_biased_flat[i*40 +: 40] = biased_mem[output_bank][output_group*4+i];
                result_shifted_flat[i*40 +: 40] = shifted_mem[output_bank][output_group*4+i];
`endif
                result_stage16_flat[i*16 +: 16] = stage16_mem[output_bank][output_group*4+i];
                result_final10_flat[i*10 +: 10] = final10_mem[output_bank][output_group*4+i];
            end
        end
    end

`ifndef SYNTHESIS
    always @(posedge clk) begin
        if (rst_n && result_valid && !result_accept)
            $error("Step102 guaranteed-accept violation vector=%0d group=%0d",
                   result_vector_id, result_group);
    end
`endif

endmodule
